function yuaSafe(array $r,UserAccessFixture $f,string $label):void
{
 assertSameValue(503,$r['status'],$label);assertSameValue(['ok'=>false,'reason'=>'SERVICE_UNAVAILABLE'],json_decode($r['body'],true),$label.' generic body');
